// Generated bytes are checked in, so ordinary builds need no C toolchain.
// Regenerate with the pinned WASI SDK image; --check verifies their inputs.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { copyFileSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const vendor = fileURLToPath(new URL("../../vendor/minimp3/", import.meta.url));
const image =
  "ghcr.io/webassembly/wasi-sdk@sha256:a4924a72705af8d5c95b84439a212200795600eb4db8dd79f3d147f4cf2f407f";
const flags = [
  "-O3",
  "-flto",
  "-ffp-contract=off",
  "-fno-stack-protector",
  "-nostdlib",
  "-mbulk-memory",
  "-Wl,--no-entry",
  "-Wl,--strip-all",
  "-Wl,--initial-memory=131072",
  "-Wl,--max-memory=131072",
  ...["input", "output", "decode", "channels", "rate"].map((name) => `-Wl,--export=${name}`),
];
const digest = createHash("sha256")
  .update(readFileSync(fileURLToPath(import.meta.url)))
  .update(readFileSync(join(here, "decoder.c")))
  .update(readFileSync(join(vendor, "minimp3.h")))
  .update(readFileSync(join(vendor, "LICENSE")))
  .digest("hex");
const target = join(here, "src/binary.ts");
if (process.argv.includes("--check")) {
  if (!readFileSync(target, "utf8").includes(`inputs: ${digest}`)) {
    throw new Error("MP3 decoder inputs changed; run pnpm --filter @swf2es/mp3 build:wasm");
  }
} else {
  const work = mkdtempSync(join(tmpdir(), "swf2es-mp3-"));
  try {
    copyFileSync(join(here, "decoder.c"), join(work, "decoder.c"));
    copyFileSync(join(vendor, "minimp3.h"), join(work, "minimp3.h"));
    const engine = ["podman", "docker"].find((name) => {
      try {
        execFileSync(name, ["--version"], { stdio: "ignore" });
        return true;
      } catch {
        return false;
      }
    });
    if (!engine) {
      throw new Error("podman or docker is needed to rebuild the MP3 decoder");
    }

    execFileSync(
      engine,
      [
        "run",
        "--rm",
        "--network=none",
        "-v",
        `${work}:/src:Z`,
        "-w",
        "/src",
        image,
        "/opt/wasi-sdk/bin/clang",
        ...flags,
        "decoder.c",
        "-o",
        "decoder.wasm",
      ],
      { stdio: "inherit" },
    );
    const bytes = readFileSync(join(work, "decoder.wasm"));
    const module = await WebAssembly.compile(bytes);
    if (WebAssembly.Module.imports(module).length) {
      throw new Error(
        `the MP3 decoder must import nothing: ${JSON.stringify(WebAssembly.Module.imports(module))}`,
      );
    }

    writeFileSync(
      target,
      `// Generated by packages/mp3/build.ts; minimp3 is CC0-1.0.\n// inputs: ${digest}\nexport const binary =\n  "${bytes.toString("base64")}";\n`,
    );
    copyFileSync(join(vendor, "LICENSE"), join(here, "LICENSE.minimp3"));
    console.log(`mp3: ${bytes.length} bytes`);
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}
